sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
    try {
        // Retrieve the current state of buttonTracker or initialize it
        let currentState = api.state["selectedPublishers"] || [];
        console.log(currentState);



        // Validate helpers.snHttp
        if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
            console.error("Error: helpers.snHttp is not properly initialized or callable.");
            return;
        }

        // Prepare the API request payload
        const requestData = {
            publisher: currentState
        };

        try {
            // Make the HTTP POST request to update the table
            const response = await helpers.snHttp("/api/985627/top_publisher", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(requestData)
            });

            // Handle the response
                console.log(response);
            if (response.status == 200 | response.response.result.status == "success") {
                console.log(` updated successfully in the table.`);


                api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'positive',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Publishers saved successfully'),
                        action: { type: 'dismiss' }
                    }
                ]
            });



            } else {
                console.error(`Failed to save publisher`, response);

                api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Failed to save publisher'),
                        action: { type: 'dismiss' }
                    }
                ]
            });

            }
        } catch (httpError) {
            console.error(`Error updating button  in the table:`, httpError);
        }
    } catch (error) {
        console.error("Unexpected error in handler:", error);
    }
    api.setState('refresh',{timestamp: Date.now()});
    api.data.get_filter_publisher_1.refresh().then(() => {
        console.log('Custom data source refreshed successfully.');
    }).catch((error) => {
        console.error('Error refreshing custom data source:', error);
    });
    // @data.get_filter_publisher_1.output.0.0
}
